import * as React from "react"

function GameLiveScore({
  className,
  ...props
}: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="game-live-score"
      className={className}
      {...props}
    >
      <div className="bg-gray-900 text-white w-full max-w-md mx-auto p-4 rounded-lg text-center mt-4">
          <div className="text-gray-400 text-sm uppercase">FT</div>
          <div className="flex items-center justify-center space-x-4 mt-2">
              <div className="flex flex-col items-center">
                  <img src="https://placeit-img-1-p.cdn.aws.placeit.net/uploads/stage/stage_image/54875/optimized_large_thumb_stage.jpg" alt="Charlotte Hornets" className="h-12 w-12 border rounded-lg border-gray-600" />
                  <span className="text-sm mt-1">Cyber Militia</span>
              </div>
              <div className="text-2xl font-bold">125 - 118</div>
              <div className="flex flex-col items-center">
                  <img src="https://placeit-img-1-p.cdn.aws.placeit.net/uploads/stage/stage_image/61995/optimized_large_thumb_stage.jpg" alt="Chicago Bulls" className="h-12 w-12 border rounded-lg border-gray-600" />
                  <span className="text-sm mt-1">Game Player</span>
              </div>
          </div>
          <div className="text-gray-400 text-sm mt-2">51-60</div>
      </div>
    </div>
  )
}

export { GameLiveScore }
